package com.transportlogistics.app.fleet.payroll.adapters.inbound.web.mappers;
import com.transportlogistics.app.fleet.payroll.domain.*;import com.transportlogistics.app.fleet.payroll.adapters.inbound.web.dto.response.DriverPayrollResponse;import org.springframework.stereotype.Component;
@Component public class DriverPayrollWebMapper{public DriverPayrollResponse response(DriverPayrollInputBatch b){var t=b.totals();return new DriverPayrollResponse(b.id(),b.type().name(),b.correctionOfBatchId(),b.periodStart(),b.periodEndExclusive(),b.cutoffAt(),b.currency(),b.lifecycle().name(),b.lines().stream().map(l->new DriverPayrollResponse.Line(l.id(),l.driverId(),l.tripId(),l.tripNumber(),l.category().name(),l.reasonCode(),l.description(),l.quantity(),l.unit().name(),l.rate(),l.amount(),l.originalLineId(),l.sourceSnapshotHash(),l.externalWorkerReference())).toList(),new DriverPayrollResponse.Totals(t.tripEarnings(),t.allowances(),t.overtime(),t.deductions(),t.provisionalNetInput()),b.preparedBy(),b.approvedBy(),b.approvedAt(),b.exportConfigurationId(),b.exportEventId(),b.version(),b.createdAt(),b.updatedAt());}public DriverPayrollResponse.Mapping response(DriverPayrollWorkerMapping m){return new DriverPayrollResponse.Mapping(m.id(),m.driverId(),m.externalSystemAlias(),m.externalWorkerReference(),m.active(),m.version(),m.updatedBy(),m.createdAt(),m.updatedAt());}}
